WITH t2f_25 AS (
  SELECT DISTINCT ca."job_id" AS jid FROM "KEBOOLA_855"."out.c-reporting-v2"."candidate_stage" cs JOIN "KEBOOLA_855"."out.c-reporting-v2"."candidate" ca ON cs."candidate_id" = ca."candidate_id" JOIN "KEBOOLA_855"."out.c-reporting-v2"."job" j ON ca."job_id" = j."job_id"
  WHERE TRY_CAST(cs."date_created" AS DATE) >= '2025-01-01' AND TRY_CAST(cs."date_created" AS DATE) < '2026-01-01' AND DATEDIFF(day, TRY_CAST(j."date_created" AS DATE), TRY_CAST(cs."date_contacted" AS DATE)) > 0
), t2fi_25 AS (
  SELECT DISTINCT ca."job_id" AS jid FROM "KEBOOLA_855"."out.c-reporting-v2"."candidate_stage" cs JOIN "KEBOOLA_855"."out.c-reporting-v2"."candidate" ca ON cs."candidate_id" = ca."candidate_id" JOIN "KEBOOLA_855"."out.c-reporting-v2"."job" j ON ca."job_id" = j."job_id"
  WHERE TRY_CAST(cs."date_created" AS DATE) >= '2025-01-01' AND TRY_CAST(cs."date_created" AS DATE) < '2026-01-01' AND TRY_CAST(cs."date_hired" AS DATE) IS NOT NULL AND DATEDIFF(day, TRY_CAST(j."date_created" AS DATE), TRY_CAST(cs."date_hired" AS DATE)) > 0
), t2f_26 AS (
  SELECT DISTINCT ca."job_id" AS jid FROM "KEBOOLA_855"."out.c-reporting-v2"."candidate_stage" cs JOIN "KEBOOLA_855"."out.c-reporting-v2"."candidate" ca ON cs."candidate_id" = ca."candidate_id" JOIN "KEBOOLA_855"."out.c-reporting-v2"."job" j ON ca."job_id" = j."job_id"
  WHERE TRY_CAST(cs."date_created" AS DATE) >= '2026-01-01' AND TRY_CAST(cs."date_created" AS DATE) < '2027-01-01' AND DATEDIFF(day, TRY_CAST(j."date_created" AS DATE), TRY_CAST(cs."date_contacted" AS DATE)) > 0
), t2fi_26 AS (
  SELECT DISTINCT ca."job_id" AS jid FROM "KEBOOLA_855"."out.c-reporting-v2"."candidate_stage" cs JOIN "KEBOOLA_855"."out.c-reporting-v2"."candidate" ca ON cs."candidate_id" = ca."candidate_id" JOIN "KEBOOLA_855"."out.c-reporting-v2"."job" j ON ca."job_id" = j."job_id"
  WHERE TRY_CAST(cs."date_created" AS DATE) >= '2026-01-01' AND TRY_CAST(cs."date_created" AS DATE) < '2027-01-01' AND TRY_CAST(cs."date_hired" AS DATE) IS NOT NULL AND DATEDIFF(day, TRY_CAST(j."date_created" AS DATE), TRY_CAST(cs."date_hired" AS DATE)) > 0
), eligible AS (SELECT DISTINCT jid FROM t2f_25 UNION SELECT jid FROM t2fi_25 UNION SELECT jid FROM t2f_26 UNION SELECT jid FROM t2fi_26),
months_agg AS (
  SELECT ca."job_id" AS jid, LISTAGG(DISTINCT TO_VARCHAR(TRY_CAST(cs."date_created" AS DATE),'YYYY-MM'),',') WITHIN GROUP (ORDER BY TO_VARCHAR(TRY_CAST(cs."date_created" AS DATE),'YYYY-MM')) AS months
  FROM "KEBOOLA_855"."out.c-reporting-v2"."candidate_stage" cs JOIN "KEBOOLA_855"."out.c-reporting-v2"."candidate" ca ON cs."candidate_id" = ca."candidate_id"
  WHERE TRY_CAST(cs."date_created" AS DATE) >= '2025-01-01' AND TRY_CAST(cs."date_created" AS DATE) < '2027-01-01' GROUP BY ca."job_id"
)
SELECT j."job_id" AS job_id, TRIM(c."client_name") AS client_name, REPLACE(j."job_title", CHR(10), ' ') AS job_title,
  COALESCE(j."job_category",'Other') AS job_category, COALESCE(j."job_subcategory",'') AS job_subcategory, COALESCE(j."job_recruiter",'') AS ta,
  TO_VARCHAR(TRY_CAST(j."date_created" AS DATE),'YYYY-MM-DD') AS date_created, TO_VARCHAR(TRY_CAST(j."date_first_hired" AS DATE),'YYYY-MM-DD') AS date_first_hired,
  TO_VARCHAR(TRY_CAST(j."date_first_hired_contacted" AS DATE),'YYYY-MM-DD') AS date_first_hired_contacted,
  DATEDIFF(day, TRY_CAST(j."date_first_hired_contacted" AS DATE), TRY_CAST(j."date_first_hired" AS DATE)) AS tth,
  DATEDIFF(day, TRY_CAST(j."date_created" AS DATE), TRY_CAST(j."date_first_hired_contacted" AS DATE)) AS t2find,
  DATEDIFF(day, TRY_CAST(j."date_created" AS DATE), TRY_CAST(j."date_first_hired" AS DATE)) AS t2fill,
  CASE WHEN j."job_id" IN (SELECT jid FROM t2f_25) THEN 1 ELSE 0 END AS has_t2f_2025,
  CASE WHEN j."job_id" IN (SELECT jid FROM t2fi_25) THEN 1 ELSE 0 END AS has_t2fi_2025,
  CASE WHEN j."job_id" IN (SELECT jid FROM t2f_26) THEN 1 ELSE 0 END AS has_t2f_2026,
  CASE WHEN j."job_id" IN (SELECT jid FROM t2fi_26) THEN 1 ELSE 0 END AS has_t2fi_2026,
  CASE WHEN j."job_category" IN ('Data Analytics','DevOps','Software Engineering','Software','Design','Product Manager','Information Technology','Quality Assurance (QA) ','Engineering Management') OR (j."job_category"='Project Manager' AND j."job_subcategory" IN ('IT Project Manager','Technical Program Manager')) THEN 'Yes' ELSE 'No' END AS tech_role,
  mpj.months AS cand_months, REPEAT('X',400) AS padding
FROM "KEBOOLA_855"."out.c-reporting-v2"."job" j
JOIN eligible e ON j."job_id" = e.jid JOIN months_agg mpj ON j."job_id" = mpj.jid
LEFT JOIN "KEBOOLA_855"."out.c-reporting-v2"."client" c ON j."client_id" = c."client_id"
WHERE j."test" <> 'true' AND j."is_external_recruiter" <> 'true'
  AND c."client_name" NOT IN ('Tribe.xyz','Kamila AI - TEST','Bubble test')
  AND TRY_CAST(j."date_first_hired" AS DATE) IS NOT NULL
